setup:
mkdir -p tickets
i=1
while [ "$i" -le 240 ]; do
  if [ $((i % 2)) -eq 0 ]; then id="TK-$((1000 + i * 7))"; else id="cs-$((30000 + i * 13))"; fi
  f="tickets/$id.txt"
  case $((i % 7)) in 0) name=Priya;; 1) name=marco;; 2) name=DeShawn;; 3) name=Ingrid;; 4) name=McKenna;; 5) name=yusuf;; 6) name=Beatriz;; esac
  case $((i % 4)) in 0) plan=Starter;; 1) plan=TEAM;; 2) plan=pro-annual;; 3) plan=Business;; esac
  case $((i % 3)) in 0) channel=email;; 1) channel=chat;; 2) channel="web form";; esac
  case $(((i / 5) % 4)) in 0) hello="Hello,";; 1) hello="Hi support team,";; 2) hello="Good morning,";; 3) hello="To whom it may concern,";; esac
  case $(((i / 4) % 4)) in 0) bye="Thanks,";; 1) bye="Regards,";; 2) bye="Best,";; 3) bye="Cheers,";; esac
  case $(((i / 3) % 3)) in 0) name2=Tomas;; 1) name2=aisha;; 2) name2=Lee;; esac
  case $(((i / 7) % 6)) in 0) ctx="We have been on this plan since $mon and use the API from two regions, mostly for nightly exports.";; 1) ctx="Context: three seats, invoices go to accounting, and the account owner is on leave until the end of $mon.";; 2) ctx="Background: we migrated from the legacy dashboard in $mon and most of our reports are scheduled, so timing matters to us.";; 3) ctx="For reference, our last invoice was number $n and the billing contact on file is still me.";; 4) ctx="A bit of context: this account is shared with a partner agency and both teams log in daily.";; 5) ctx="We are a small team of four; the account was set up in $mon and has been billed monthly since.";; esac
  case $((i % 6)) in 0) mon=January;; 1) mon=March;; 2) mon=May;; 3) mon=July;; 4) mon=September;; 5) mon=November;; esac
  date=$(printf '2026-%02d-%02d' $((1 + i % 12)) $((1 + i % 28)))
  acct=$((40000 + i * 31))
  n=$((100 + i * 3))
  c=$((i % 9)); v=$(((i / 9) % 3))
  case "$c$v" in
    00) body="Please do NOT cancel my subscription. I got an email saying it was scheduled to end and I never asked for that - no cancellation, keep it active.";;
    01) body="Somebody on my team may have requested a cancellation - please confirm you did not close my account, and if a request is pending, discard it.";;
    02) body="I never asked you to end my plan or terminate anything, so please make sure nothing is cancelled on your side. Everything should stay as it is.";;
    10) body="My flight was cancelled, so please move my workshop booking to $mon. My subscription itself is fine.";;
    11) body="I cancelled the wrong order this morning (the printer instead of the toner) - please restore it and charge me as before.";;
    12) body="Please cancel the duplicate invoice #$n you sent on $date; the first one is already paid and my $plan plan should keep running.";;
    20) body="I am considering cancelling unless the export bug is fixed by $mon. For now, please just tell me when a fix is planned.";;
    21) body="If the sync problem is not resolved before the renewal date I may cancel and not renew, but right now I only need the sync issue looked at.";;
    22) body="A colleague suggested we terminate the plan if prices rise again; before deciding I would like a quote for the annual rate.";;
    30) body="I cancelled last month and was still charged on $date. Please refund that charge; I do not want the account back, I just want the money returned.";;
    31) body="My plan already ended in $mon when I cancelled it, but a renewal charge appeared anyway. Please refund it and confirm there are no further charges scheduled - the account is already closed.";;
    32) body="Refund request: the plan was terminated on $date at my request and I was billed again a week later. Please return the charge to my card.";;
    40) body="I cancelled by mistake yesterday while cleaning up old settings. Please reactivate the subscription on the same $plan plan.";;
    41) body="Please undo the cancellation submitted on $date - I clicked the wrong button and want to keep the $plan plan.";;
    42) body="Our account shows as closed after someone requested a termination; that was an error, please reopen it and keep billing as before.";;
    50) body="My colleague $name2 cancelled his seat last week; I want to stay on the plan, so please only remove his login and leave mine.";;
    51) body="The previous owner of this account was done with the product and cancelled her subscription before handing it over. I am the new owner and want to keep it running - please just move the billing contact to me.";;
    52) body="One of our contractors unsubscribed from the shared workspace. That is fine - we decided to keep the workspace - but please make sure my own plan was not affected.";;
    60) body="Please end my trial early and move me to the paid $plan plan today; I want to start being billed now.";;
    61) body="Terminate the free tier on my account and switch me to the annual $plan plan - here is the purchase order number: PO-$n.";;
    62) body="Please close my account's free sandbox and consolidate everything into the paid workspace; keep billing the company card.";;
    70) body="Please stop billing my old card ending $n and charge the new one instead; the plan stays exactly as it is.";;
    71) body="Please unsubscribe me from the marketing newsletter only. Keep the product emails and my subscription.";;
    72) body="Please terminate the old API key issued in $mon and generate a new one; my plan itself should stay as it is.";;
    80) body="Where is the cancel button on the export dialog? It used to be at the bottom and now the export runs before I can stop it.";;
    81) body="Quick question about your cancellation policy for the annual plan: is it prorated? I am not planning to leave, just comparing plans for the budget.";;
    82) body="The webhook for cancelled events fires twice for every order. Can you check the dedupe on your side?";;
  esac
  if [ "$i" -eq 138 ]; then body="I have decided to leave. Please end my plan at the end of this billing cycle and do not renew it - I am done with the service and want no further charges after this period."; fi
  printf 'Ticket %s - opened %s - channel: %s\n\n%s\n\nThis is %s, account %s (%s plan, billed monthly).\n%s\n%s\n\n%s\n%s\n' "$id" "$date" "$channel" "$hello" "$name" "$acct" "$plan" "$ctx" "$body" "$bye" "$name" > "$f"
  i=$((i + 1))
done
{ cat "$HOME/.arnes/runs.jsonl" 2>/dev/null || true; } | wc -l | tr -d ' ' > .runs-before
